// ─── EDIT ONLY THESE TWO LINES (no n8n env variables needed) ───
const PUBLIC_APP_URL = 'https://crm-agent-bot-hj5k.vercel.app';
const INGEST_SECRET = 'PASTE_YOUR_INGEST_SECRET_FROM_VERCEL';
// Use the production URL only — not the long preview deployment URL.
// INGEST_SECRET must match the INGEST_SECRET value in Vercel exactly.
// ─────────────────────────────────────────────────────────────────

return [{
  json: {
    publicAppUrl: String(PUBLIC_APP_URL || '').trim().replace(/\/+$/, ''),
    ingestSecret: String(INGEST_SECRET || '').trim(),
  },
}];

const body = $json || {};
const results = Array.isArray(body.results) ? body.results : [];
const synced = results.filter((item) => !item.error);
const failed = results.filter((item) => item.error);
const totalRows = synced.reduce((sum, item) => sum + Number(item.stored || 0), 0);
return [{
  json: {
    ok: Boolean(body.ok),
    error: body.error || null,
    persisted: Boolean(body.persisted),
    syncedCount: synced.length,
    failedCount: failed.length,
    totalLeadRows: totalRows,
    authorizedUsers: body.authorizedUsers ?? null,
    failures: failed.map((item) => ({ sourceKey: item.sourceKey, error: item.error })),
    sample: synced.slice(0, 5).map((item) => ({
      sourceKey: item.sourceKey,
      stored: item.stored,
      ftdStored: item.ftdStored,
      infoStored: item.infoStored,
      totalLeads: item.totalLeads,
      totalFtd: item.totalFtd,
    })),
  },
}];
